// CreateRecurringEvents is the resolver for the createRecurringEvents field.
func (r *mutationResolver) CreateRecurringEvents(ctx context.Context, input model.EventInput, endDate time.Time) ([]*model.Event, error) {
	// Validate input
	if input.Recurring == nil || *input.Recurring == model.RecurringTypeNone {
		return nil, fmt.Errorf("recurring type must be specified for creating recurring events")
	}

	if endDate.Before(input.Date) {
		return nil, fmt.Errorf("end date must be after start date")
	}

	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get service ID: %v", err)
	}

	serviceID, err := uuid.Parse(*serviceIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid service ID: %w", err)
	}

	// Validate time format
	if !helper.IsValidTimeFormat(input.StartTime) {
		return nil, fmt.Errorf("invalid time format for startTime. Please use HH:MM format (24-hour)")
	}

	var events []*model.Event
	currentDate := input.Date

	// Create events based on recurring pattern until end date
	for !currentDate.After(endDate) {
		event := &model.Event{
			Name:         input.Name,
			Date:         currentDate,
			StartTime:    input.StartTime,
			Duration:     input.Duration,
			Location:     input.Location,
			Instructor:   input.Instructor,
			MaxAttendees: input.MaxAttendees,
			Price:        input.Price,
			Description:  input.Description,
			Recurring:    input.Recurring,

			ServiceID: serviceID.String(),
		}

		events = append(events, event)

		// Calculate next date based on recurring type
		switch *input.Recurring {
		case model.RecurringTypeDaily:
			currentDate = currentDate.AddDate(0, 0, 1)
		case model.RecurringTypeWeekly:
			currentDate = currentDate.AddDate(0, 0, 7)
		case model.RecurringTypeBiweekly:
			currentDate = currentDate.AddDate(0, 0, 14)
		case model.RecurringTypeMonthly:
			currentDate = currentDate.AddDate(0, 1, 0)
		default:
			return nil, fmt.Errorf("unsupported recurring type")
		}
	}

	// Save all events to the database in a transaction
	err = r.DB.Transaction(func(tx *gorm.DB) error {
		for _, event := range events {
			if err := tx.Create(event).Error; err != nil {
				return err
			}
		}
		return nil
	})

	if err != nil {
		return nil, fmt.Errorf("failed to create recurring events: %w", err)
	}

	return events, nil
}

