// GetBookedData is the resolver for the getBookedData field.
func (r *queryResolver) GetBookedData(ctx context.Context) ([]*model.BookedData, error) {
	serviceIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get service ID: %v", err)
	}
	serviceID, err := uuid.Parse(*serviceIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid service ID: %w", err)
	}

	// First, find all events by this service
	var events []*model.Event
	if err := r.DB.Where("service_id = ?", serviceID.String()).Find(&events).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch events: %w", err)
	}

	// Create the result array
	var bookedData []*model.BookedData

	// For each event, find its bookings and associated user data
	for _, event := range events {
		// Find all bookings for this event
		var bookings []*model.EventBookings
		if err := r.DB.Where("event_id = ?", event.ID.String()).Find(&bookings).Error; err != nil {
			return nil, fmt.Errorf("failed to fetch bookings for event %s: %w", event.ID.String(), err)
		}

		// Skip events with no bookings
		if len(bookings) == 0 {
			continue
		}

		// Collect user data for all bookings
		var usersData []*model.UserData

		for _, booking := range bookings {
			// For each booking, we need to determine if it's a User or Service
			// We'll query both tables and use the one that returns a result

			// First try User table
			var user model.User
			userErr := r.DB.Where("id = ?", booking.UserID).First(&user).Error

			// Then try Service table
			var service model.Service
			serviceErr := r.DB.Where("id = ?", booking.UserID).First(&service).Error

			// Create UserData based on which query succeeded
			var userData *model.UserData

			if userErr == nil {
				// It's a User
				userData = &model.UserData{
					ID:         user.ID.String(),
					Name:       user.Name,
					Number:     user.Number,
					NumberType: user.NumberType,
					Type:       user.Type,
				}
			} else if serviceErr == nil {
				// It's a Service
				userData = &model.UserData{
					ID:         service.ID.String(),
					Name:       service.Name,
					Number:     service.Number,
					NumberType: "Unkown", // Assuming services don't have a number type field
					Type:       service.Type,
				}
			} else {
				// Neither query succeeded, log an error but continue
				continue
			}

			usersData = append(usersData, userData)
		}

		// Add the event and its users to the result
		bookedData = append(bookedData, &model.BookedData{
			Event:     event,
			UsersData: usersData,
		})
	}

	return bookedData, nil
}

